import React from 'react';
import {
    Box,
    Paper,
    Typography,
    Button,
    Grid,
    List,
    ListItem,
    ListItemText,
    Divider,
    CircularProgress,
    Alert,
    Snackbar,
    Skeleton
} from '@mui/material';
import { ReportData } from '../../types/form';
import { downloadReport } from '../../services/api';
import { useState } from 'react';

interface ReportProps {
    data?: ReportData;
    isLoading?: boolean;
    error?: Error | null;
}

export const Report: React.FC<ReportProps> = ({ data, isLoading, error }) => {
    const [downloadingFormat, setDownloadingFormat] = useState<string | null>(null);
    const [downloadError, setDownloadError] = useState<string | null>(null);

    const handleDownload = async (format: 'pdf' | 'markdown' | 'json') => {
        setDownloadingFormat(format);
        setDownloadError(null);
        try {
            const blob = await downloadReport(format);
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `report.${format}`;
            document.body.appendChild(a);
            a.click();
            window.URL.revokeObjectURL(url);
            document.body.removeChild(a);
        } catch (error) {
            console.error(`Error downloading ${format} report:`, error);
            setDownloadError(`Failed to download ${format} report`);
        } finally {
            setDownloadingFormat(null);
        }
    };

    if (error) {
        return (
            <Paper elevation={3} sx={{ p: 3, mt: 3 }}>
                <Alert severity="error" sx={{ mb: 2 }}>
                    {error.message}
                </Alert>
            </Paper>
        );
    }

    if (isLoading) {
        return (
            <Paper elevation={3} sx={{ p: 3, mt: 3 }}>
                <Skeleton variant="text" width="60%" height={40} sx={{ mb: 2 }} />
                <Skeleton variant="rectangular" height={200} sx={{ mb: 2 }} />
                <Skeleton variant="rectangular" height={100} />
            </Paper>
        );
    }

    if (!data) {
        return (
            <Paper elevation={3} sx={{ p: 3, mt: 3, textAlign: 'center' }}>
                <Typography variant="h6" color="text.secondary" gutterBottom>
                    No Report Generated Yet
                </Typography>
                <Typography color="text.secondary">
                    Fill out the form and click "Generate Report" to see your results here.
                </Typography>
            </Paper>
        );
    }

    return (
        <Paper elevation={3} sx={{ p: 3, mt: 3, position: 'relative' }}>
            <Typography variant="h5" gutterBottom>
                Report Summary
            </Typography>

            <Grid container spacing={2}>
                <Grid item xs={12} md={6}>
                    <Box sx={{ mb: 3 }}>
                        <Typography variant="subtitle1" color="primary">
                            Personal Information
                        </Typography>
                        <Typography>
                            <strong>Name:</strong> {data.name}
                        </Typography>
                        <Typography>
                            <strong>Current Weight:</strong> {data.current_weight} lbs
                        </Typography>
                        <Typography>
                            <strong>Current Body Fat:</strong> {data.current_bf}%
                        </Typography>
                        <Typography>
                            <strong>Goal Weight:</strong> {data.goal_weight} lbs
                        </Typography>
                        <Typography>
                            <strong>Goal Body Fat:</strong> {data.goal_bf}%
                        </Typography>
                    </Box>
                </Grid>

                {data.recommendations && data.recommendations.length > 0 && (
                    <Grid item xs={12}>
                        <Typography variant="subtitle1" color="primary" gutterBottom>
                            Recommendations
                        </Typography>
                        <List>
                            {data.recommendations.map((rec, index) => (
                                <React.Fragment key={index}>
                                    <ListItem>
                                        <ListItemText primary={rec} />
                                    </ListItem>
                                    {index < data.recommendations!.length - 1 && <Divider />}
                                </React.Fragment>
                            ))}
                        </List>
                    </Grid>
                )}

                {data.timeline && (
                    <Grid item xs={12}>
                        <Typography variant="subtitle1" color="primary" gutterBottom>
                            Timeline
                        </Typography>
                        <Typography paragraph>
                            {data.timeline}
                        </Typography>
                    </Grid>
                )}

                <Grid item xs={12}>
                    <Box sx={{ mt: 3 }}>
                        <Typography variant="subtitle1" color="primary" gutterBottom>
                            Download Report
                        </Typography>
                        <Grid container spacing={2}>
                            <Grid item>
                                <Button
                                    variant="contained"
                                    onClick={() => handleDownload('pdf')}
                                    disabled={!!downloadingFormat}
                                    startIcon={downloadingFormat === 'pdf' ? <CircularProgress size={20} /> : null}
                                >
                                    {downloadingFormat === 'pdf' ? 'Downloading...' : 'Download PDF'}
                                </Button>
                            </Grid>
                            <Grid item>
                                <Button
                                    variant="contained"
                                    onClick={() => handleDownload('markdown')}
                                    disabled={!!downloadingFormat}
                                    startIcon={downloadingFormat === 'markdown' ? <CircularProgress size={20} /> : null}
                                >
                                    {downloadingFormat === 'markdown' ? 'Downloading...' : 'Download Markdown'}
                                </Button>
                            </Grid>
                            <Grid item>
                                <Button
                                    variant="contained"
                                    onClick={() => handleDownload('json')}
                                    disabled={!!downloadingFormat}
                                    startIcon={downloadingFormat === 'json' ? <CircularProgress size={20} /> : null}
                                >
                                    {downloadingFormat === 'json' ? 'Downloading...' : 'Download JSON'}
                                </Button>
                            </Grid>
                        </Grid>
                    </Box>
                </Grid>

                <Snackbar
                    open={!!downloadError}
                    autoHideDuration={6000}
                    onClose={() => setDownloadError(null)}
                >
                    <Alert onClose={() => setDownloadError(null)} severity="error">
                        {downloadError}
                    </Alert>
                </Snackbar>
            </Grid>
        </Paper>
    );
};
