import { Box } from '@mui/material';
import { Layout } from './components/Layout/Layout';
import { MainForm } from './components/Form/MainForm';
import { Report } from './components/Report/Report';
import { WeeklyUpdate } from './components/WeeklyUpdate/WeeklyUpdate';
import { useFormState } from './hooks/useFormState';

function App() {
  const { 
    reportData, 
    weeklyReportData, 
    isGeneratingReport, 
    isUpdatingWeekly,
    error 
  } = useFormState();
  
  const displayData = weeklyReportData || reportData;
  const isLoading = isGeneratingReport || isUpdatingWeekly;

  return (
    <Layout>
      {/* Left Column: Forms */}
      <Box>
        <MainForm />
        <WeeklyUpdate />
      </Box>

      {/* Right Column: Report */}
      <Box>
        <Report 
          data={displayData}
          isLoading={isLoading}
          error={error as Error | null}
        />
      </Box>
    </Layout>
  );
}

export default App;
