import React from 'react';
import {
    Box,
    TextField,
    Button,
    Grid,
    Typography,
    CircularProgress,
    Paper
} from '@mui/material';
import { useFormState } from '../../hooks/useFormState';

export const WeeklyUpdate: React.FC = () => {
    const {
        weeklyData,
        handleWeeklyInputChange,
        handleWeeklyUpdate,
        isUpdatingWeekly,
        error
    } = useFormState();

    return (
        <Paper elevation={3} sx={{ p: 3, mt: 3 }}>
            <Typography variant="h6" gutterBottom>
                Weekly Update
            </Typography>

            <Box component="form" onSubmit={handleWeeklyUpdate}>
                <Grid container spacing={3}>
                    <Grid item xs={12} sm={6}>
                        <TextField
                            fullWidth
                            type="number"
                            label="Current Weight (lbs)"
                            value={weeklyData.weekly_weight}
                            onChange={(e) => handleWeeklyInputChange('weekly_weight', parseFloat(e.target.value))}
                            required
                            inputProps={{ step: 0.1, min: 0, max: 1000 }}
                        />
                    </Grid>

                    <Grid item xs={12} sm={6}>
                        <TextField
                            fullWidth
                            type="number"
                            label="Current Body Fat (%)"
                            value={weeklyData.weekly_bf}
                            onChange={(e) => handleWeeklyInputChange('weekly_bf', parseFloat(e.target.value))}
                            required
                            inputProps={{ step: 0.1, min: 0, max: 100 }}
                        />
                    </Grid>

                    {error && (
                        <Grid item xs={12}>
                            <Typography color="error">{error.message}</Typography>
                        </Grid>
                    )}

                    <Grid item xs={12}>
                        <Button
                            type="submit"
                            variant="contained"
                            color="primary"
                            fullWidth
                            disabled={isUpdatingWeekly}
                            startIcon={isUpdatingWeekly ? <CircularProgress size={20} /> : null}
                        >
                            Update Weekly Progress
                        </Button>
                    </Grid>
                </Grid>
            </Box>
        </Paper>
    );
};
