import { useState } from 'react';
import { useMutation, useQuery } from '@tanstack/react-query';
import { FormData, WeeklyUpdateData, ReportData, ApiResponse } from '../types/form';
import { generateReport, updateWeekly, getLastReportData, getTestData } from '../services/api';

export const useFormState = () => {
    const [formData, setFormData] = useState<FormData>({
        name: '',
        current_weight: 0,
        current_bf: 0,
        goal_weight: 0,
        goal_bf: 0,
        height_feet: 5,
        height_inches: 0,
        protein_intake: 0,
        activity_level: 1,
        workout_days: 0,
        resistance_training: false,
        is_athlete: false,
        workout_type: 'Bodybuilding',
        job_activity: 'sedentary',
        leisure_activity: 'sedentary',
        experience_level: 'Beginner (0-1 year)',
        start_date: new Date().toISOString().split('T')[0],
        end_date: new Date(Date.now() + 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        dob: '1990-01-01', // Default DOB, user should change this
        gender: 'm'    // Default gender, user should change this
    });

    const [weeklyData, setWeeklyData] = useState<WeeklyUpdateData>({
        weekly_weight: 0,
        weekly_bf: 0
    });

    // Query for last report data
    const { isLoading: isLoadingLastReport, refetch: refetchLastReport } = useQuery({
        queryKey: ['lastReport'],
        queryFn: getLastReportData,
        enabled: false, // Don't load automatically
        retry: false   // Don't retry on failure
    });

    // Mutation for generating report
    const generateReportMutation = useMutation<ApiResponse<ReportData>, Error, FormData>({
        mutationFn: generateReport,
        onSuccess: (data) => {
            if (!data.success) {
                throw new Error(data.error || 'Failed to generate report');
            }
            console.log('Report generated successfully:', data);
        },
        onError: (error: any) => {
            console.error('Error generating report:', error);
            // Extract error message from backend response if available
            const errorMessage = error.response?.data?.error || error.message || 'Failed to generate report';
            throw new Error(errorMessage);
        }
    });

    // Mutation for weekly update
    const weeklyUpdateMutation = useMutation({
        mutationFn: updateWeekly,
        onSuccess: (data: ApiResponse<ReportData>) => {
            if (!data.success) {
                throw new Error(data.error || 'Failed to update weekly data');
            }
            console.log('Weekly update successful:', data);
        },
        onError: (error: any) => {
            console.error('Error updating weekly data:', error);
            const errorMessage = error.response?.data?.error || error.message || 'Failed to update weekly data';
            throw new Error(errorMessage);
        }
    });

    const handleInputChange = (name: keyof FormData, value: string | number | boolean) => {
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleWeeklyInputChange = (name: keyof WeeklyUpdateData, value: number) => {
        setWeeklyData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        
        console.log('Submitting form data:', formData);
        try {
            const result = await generateReportMutation.mutateAsync(formData);
            console.log('Report generation result:', result);
            if (!result.success) {
                throw new Error(result.error || 'Failed to generate report');
            }
        } catch (error: any) {
            console.error('Submit error:', error);
            // The error will be handled by the mutation's onError callback
            throw error;
        }
    };

    const handleWeeklyUpdate = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await weeklyUpdateMutation.mutateAsync(weeklyData);
        } catch (error) {
            console.error('Weekly update error:', error);
        }
    };

    const loadTestData = async () => {
        try {
            const result = await getTestData();
            if (result.success && result.data) {
                setFormData(result.data);
            }
        } catch (error: any) {
            console.error('Load test data error:', error);
            const errorMessage = error.response?.data?.error || error.message || 'Failed to load test data';
            throw new Error(errorMessage);
        }
    };

    const loadLastReport = async () => {
        try {
            const result = await refetchLastReport();
            if (result.data?.success && result.data?.data) {
                setFormData(result.data.data);
                setWeeklyData({
                    weekly_weight: result.data.data.current_weight,
                    weekly_bf: result.data.data.current_bf
                });
            }
        } catch (error: any) {
            console.error('Load last report error:', error);
            const errorMessage = error.response?.data?.error || error.message || 'Failed to load last report';
            throw new Error(errorMessage);
        }
    };

    return {
        formData,
        weeklyData,
        handleInputChange,
        handleWeeklyInputChange,
        handleSubmit,
        handleWeeklyUpdate,
        loadLastReport,
        loadTestData,
        isLoadingLastReport,
        isGeneratingReport: generateReportMutation.isPending,
        isUpdatingWeekly: weeklyUpdateMutation.isPending,
        reportData: generateReportMutation.data?.data,
        weeklyReportData: weeklyUpdateMutation.data?.data,
        error: generateReportMutation.error || weeklyUpdateMutation.error
    };
};
