import axios from 'axios';
import { FormData, WeeklyUpdateData, ReportData, ApiResponse } from '../types/form';

const BASE_URL = '/api'; // Proxied through Vite development server

const api = axios.create({
    baseURL: BASE_URL,
    headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    },
    withCredentials: false,
    timeout: 60000 // 60 second timeout
});

// Health check function
export const checkHealth = async (): Promise<boolean> => {
    try {
        console.log('Checking API health...');
        const response = await api.get('/health');
        console.log('Health check response:', response.data);
        return response.data?.status === 'healthy';
    } catch (error) {
        if (axios.isAxiosError(error)) {
            console.error('Health check failed:', {
                message: error.message,
                code: error.code,
                response: error.response?.data,
                url: error.config?.url
            });
        } else {
            console.error('Health check failed with unknown error:', error);
        }
        return false;
    }
};

// Initialize API with health check
const initApi = async () => {
    try {
        const isHealthy = await checkHealth();
        if (!isHealthy) {
            console.error('API health check failed');
        } else {
            console.log('API health check passed');
        }
    } catch (error) {
        console.error('Error during API initialization:', error);
    }
};

// Run health check on startup
initApi();

// Add request interceptor for logging
api.interceptors.request.use(
    config => {
        console.log('Making request to:', config.url);
        return config;
    },
    error => {
        console.error('Request error:', error);
        return Promise.reject(error);
    }
);

// Add response interceptor for retrying failed requests
api.interceptors.response.use(
    response => response,
    async error => {
        console.error('Response error:', error);
        
        const { config, message } = error;
        
        // If there's no config, this is not a request error
        if (!config) {
            return Promise.reject(error);
        }

        // Don't retry if we've already retried
        if (config._retry) {
            console.error('Request failed after retry:', message);
            return Promise.reject(error);
        }

        // Only retry GET requests or specific errors
        if (config.method === 'get' || message.includes('Network Error')) {
            config._retry = true;
            console.log('Retrying request...');
            return api(config);
        }

        return Promise.reject(error);
    }
);

export const generateReport = async (formData: FormData): Promise<ApiResponse<ReportData>> => {
    try {
        // Check API health before making request
        const isHealthy = await checkHealth();
        if (!isHealthy) {
            throw new Error('API is not available. Please try again later.');
        }

        // Validate workout type
        if (!['Bodybuilding', 'Cardio', 'General Fitness'].includes(formData.workout_type)) {
            throw new Error('Invalid workout type');
        }

        const response = await api.post('/generate-report', formData);
        return response.data;
    } catch (error) {
        if (axios.isAxiosError(error)) {
            const errorMessage = error.response?.data?.error || error.message || 'Failed to generate report';
            console.error('Generate report error:', {
                status: error.response?.status,
                data: error.response?.data,
                message: errorMessage
            });
            throw new Error(errorMessage);
        }
        throw error;
    }
};

export const updateWeekly = async (data: WeeklyUpdateData): Promise<ApiResponse<ReportData>> => {
    try {
        const response = await api.post('/update-weekly', data);
        return response.data;
    } catch (error) {
        if (axios.isAxiosError(error)) {
            throw new Error(error.response?.data?.error || 'Failed to update weekly data');
        }
        throw error;
    }
};

export const getTestData = async (): Promise<ApiResponse<FormData>> => {
    try {
        console.log('Fetching test data');
        const response = await api.get('/test-data');
        console.log('Test data response:', response.data);
        return response.data;
    } catch (error) {
        if (axios.isAxiosError(error)) {
            console.error('Error fetching test data:', {
                status: error.response?.status,
                data: error.response?.data,
                message: error.message
            });
            throw new Error(error.response?.data?.error || 'Failed to fetch test data');
        }
        throw error;
    }
};

export const getLastReportData = async (): Promise<ApiResponse<FormData>> => {
    try {
        console.log('Fetching last report data from:', `${BASE_URL}/last-report`);
        const response = await api.get('/last-report');
        console.log('Last report data response:', response.data);
        return response.data;
    } catch (error) {
        if (axios.isAxiosError(error)) {
            console.error('Error fetching last report:', {
                status: error.response?.status,
                data: error.response?.data,
                message: error.message
            });
            throw new Error(error.response?.data?.error || 'Failed to fetch last report data');
        }
        throw error;
    }
};

export const downloadReport = async (format: 'pdf' | 'markdown' | 'json'): Promise<Blob> => {
    try {
        const response = await api.get(`/download/${format}`, {
            responseType: 'blob'
        });
        return response.data;
    } catch (error) {
        if (axios.isAxiosError(error)) {
            throw new Error(`Failed to download ${format} report`);
        }
        throw error;
    }
};

// Add an interceptor to handle errors globally
api.interceptors.response.use(
    response => response,
    error => {
        console.error('API Error:', error);
        if (error.response?.status === 500) {
            console.error('Server Error:', error.response.data);
        }
        return Promise.reject(error);
    }
);

export default api;
