import React, { useEffect, useState } from 'react';
import {
    Box,
    TextField,
    Select,
    MenuItem,
    FormControl,
    InputLabel,
    Checkbox,
    FormControlLabel,
    Button,
    Grid,
    CircularProgress,
    Alert,
    AlertTitle
} from '@mui/material';
import { useFormState } from '../../hooks/useFormState';
import { checkHealth } from '../../services/api';

const activityLevels = [
    { value: 1, label: 'Little to no exercise' },
    { value: 2, label: 'Light exercise/sports 1-3 days/week' },
    { value: 3, label: 'Moderate exercise/sports 3-5 days/week' },
    { value: 4, label: 'Hard exercise/sports 6-7 days a week' },
    { value: 5, label: 'Very hard exercise/sports & a physical job' }
];

const workoutTypes = ['Bodybuilding', 'Cardio', 'General Fitness'];
const activityTypes = ['sedentary', 'light', 'moderate', 'active'];
const experienceLevels = [
    'Beginner (0-1 year)',
    'Novice (1-2 years)',
    'Intermediate (2-4 years)',
    'Advanced (4-10 years)',
    'Elite (10+ years)'
];

export const MainForm: React.FC = () => {
    const [apiStatus, setApiStatus] = useState<'checking' | 'healthy' | 'error'>('checking');
    const {
        formData,
        handleInputChange,
        handleSubmit,
        loadLastReport,
        loadTestData,
        isLoadingLastReport,
        isGeneratingReport,
        error
    } = useFormState();

    useEffect(() => {
        const checkApiHealth = async () => {
            try {
                const isHealthy = await checkHealth();
                setApiStatus(isHealthy ? 'healthy' : 'error');
            } catch (error) {
                console.error('Health check error:', error);
                setApiStatus('error');
            }
        };

        checkApiHealth();
        // Check health every 30 seconds
        const interval = setInterval(checkApiHealth, 30000);
        return () => clearInterval(interval);
    }, []);

    if (apiStatus === 'checking') {
        return (
            <Box display="flex" justifyContent="center" alignItems="center" minHeight="200px">
                <CircularProgress />
            </Box>
        );
    }

    if (apiStatus === 'error') {
        return (
            <Alert severity="error" sx={{ mt: 2 }}>
                <AlertTitle>Connection Error</AlertTitle>
                Unable to connect to the server. Please try again later.
            </Alert>
        );
    }

    return (
        <Box component="form" onSubmit={handleSubmit} sx={{ mt: 3 }}>
            <Grid container spacing={3}>
                <Grid item xs={12}>
                    <Grid container spacing={2}>
                        <Grid item>
                            <Button
                                variant="contained"
                                color="secondary"
                                onClick={loadLastReport}
                                disabled={isLoadingLastReport}
                                startIcon={isLoadingLastReport ? <CircularProgress size={20} /> : null}
                            >
                                Fill with Last Report Data
                            </Button>
                        </Grid>
                        <Grid item>
                            <Button
                                variant="contained"
                                color="primary"
                                onClick={loadTestData}
                            >
                                Fill with Test Data
                            </Button>
                        </Grid>
                    </Grid>
                </Grid>

                {error && (
                    <Grid item xs={12}>
                        <Alert severity="error">
                            <AlertTitle>Error</AlertTitle>
                            {error.message}
                        </Alert>
                    </Grid>
                )}

                <Grid item xs={12}>
                    <TextField
                        fullWidth
                        label="Name"
                        value={formData.name}
                        onChange={(e) => handleInputChange('name', e.target.value)}
                        required
                    />
                </Grid>

                <Grid item xs={12} sm={6}>
                    <TextField
                        fullWidth
                        label="Start Date"
                        value={formData.start_date}
                        onChange={(e) => handleInputChange('start_date', e.target.value)}
                        required
                        type="date"
                        InputLabelProps={{ shrink: true }}
                    />
                </Grid>

                <Grid item xs={12} sm={6}>
                    <TextField
                        fullWidth
                        label="End Date"
                        value={formData.end_date}
                        onChange={(e) => handleInputChange('end_date', e.target.value)}
                        required
                        type="date"
                        InputLabelProps={{ shrink: true }}
                    />
                </Grid>

                <Grid item xs={12} sm={6}>
                    <TextField
                        fullWidth
                        label="Date of Birth"
                        value={formData.dob}
                        onChange={(e) => handleInputChange('dob', e.target.value)}
                        required
                        type="date"
                        InputLabelProps={{ shrink: true }}
                    />
                </Grid>

                <Grid item xs={12} sm={6}>
                    <FormControl fullWidth required>
                        <InputLabel>Gender</InputLabel>
                        <Select
                            value={formData.gender}
                            onChange={(e) => handleInputChange('gender', e.target.value)}
                        >
                            <MenuItem value="m">Male</MenuItem>
                            <MenuItem value="f">Female</MenuItem>
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12} sm={6}>
                    <TextField
                        fullWidth
                        type="number"
                        label="Current Weight (lbs)"
                        value={formData.current_weight}
                        onChange={(e) => handleInputChange('current_weight', parseFloat(e.target.value))}
                        required
                        inputProps={{ step: 0.1, min: 0, max: 1000 }}
                    />
                </Grid>

                <Grid item xs={12} sm={6}>
                    <TextField
                        fullWidth
                        type="number"
                        label="Current Body Fat (%)"
                        value={formData.current_bf}
                        onChange={(e) => handleInputChange('current_bf', parseFloat(e.target.value))}
                        required
                        inputProps={{ step: 0.1, min: 0, max: 100 }}
                    />
                </Grid>

                <Grid item xs={12} sm={6}>
                    <TextField
                        fullWidth
                        type="number"
                        label="Goal Weight (lbs)"
                        value={formData.goal_weight}
                        onChange={(e) => handleInputChange('goal_weight', parseFloat(e.target.value))}
                        required
                        inputProps={{ step: 0.1, min: 0, max: 1000 }}
                    />
                </Grid>

                <Grid item xs={12} sm={6}>
                    <TextField
                        fullWidth
                        type="number"
                        label="Goal Body Fat (%)"
                        value={formData.goal_bf}
                        onChange={(e) => handleInputChange('goal_bf', parseFloat(e.target.value))}
                        required
                        inputProps={{ step: 0.1, min: 0, max: 100 }}
                    />
                </Grid>

                <Grid item xs={12} sm={6}>
                    <FormControl fullWidth>
                        <InputLabel>Height (Feet)</InputLabel>
                        <Select
                            value={formData.height_feet}
                            onChange={(e) => handleInputChange('height_feet', parseInt(e.target.value as string))}
                            required
                        >
                            {[4, 5, 6, 7].map((feet) => (
                                <MenuItem key={feet} value={feet}>{feet}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12} sm={6}>
                    <FormControl fullWidth>
                        <InputLabel>Height (Inches)</InputLabel>
                        <Select
                            value={formData.height_inches}
                            onChange={(e) => handleInputChange('height_inches', parseInt(e.target.value as string))}
                            required
                        >
                            {Array.from({ length: 12 }, (_, i) => (
                                <MenuItem key={i} value={i}>{i}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12}>
                    <TextField
                        fullWidth
                        type="number"
                        label="Protein Intake (g)"
                        value={formData.protein_intake}
                        onChange={(e) => handleInputChange('protein_intake', parseFloat(e.target.value))}
                        required
                        inputProps={{ step: 1, min: 0, max: 1000 }}
                    />
                </Grid>

                <Grid item xs={12}>
                    <FormControl fullWidth>
                        <InputLabel>Activity Level</InputLabel>
                        <Select
                            value={formData.activity_level}
                            onChange={(e) => handleInputChange('activity_level', parseInt(e.target.value as string))}
                            required
                        >
                            {activityLevels.map((level) => (
                                <MenuItem key={level.value} value={level.value}>{level.label}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12}>
                    <FormControl fullWidth>
                        <InputLabel>Workout Days per Week</InputLabel>
                        <Select
                            value={formData.workout_days}
                            onChange={(e) => handleInputChange('workout_days', parseInt(e.target.value as string))}
                            required
                        >
                            {Array.from({ length: 8 }, (_, i) => (
                                <MenuItem key={i} value={i}>{i}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12} sm={6}>
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={formData.resistance_training}
                                onChange={(e) => handleInputChange('resistance_training', e.target.checked)}
                            />
                        }
                        label="Resistance Training"
                    />
                </Grid>

                <Grid item xs={12} sm={6}>
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={formData.is_athlete}
                                onChange={(e) => handleInputChange('is_athlete', e.target.checked)}
                            />
                        }
                        label="Is an Athlete"
                    />
                </Grid>

                <Grid item xs={12}>
                    <FormControl fullWidth>
                        <InputLabel>Workout Type</InputLabel>
                        <Select
                            value={formData.workout_type}
                            onChange={(e) => handleInputChange('workout_type', e.target.value)}
                            required
                        >
                            {workoutTypes.map((type) => (
                                <MenuItem key={type} value={type}>{type}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12} sm={6}>
                    <FormControl fullWidth>
                        <InputLabel>Job Activity</InputLabel>
                        <Select
                            value={formData.job_activity}
                            onChange={(e) => handleInputChange('job_activity', e.target.value)}
                            required
                        >
                            {activityTypes.map((type) => (
                                <MenuItem key={type} value={type}>{type}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12} sm={6}>
                    <FormControl fullWidth>
                        <InputLabel>Leisure Activity</InputLabel>
                        <Select
                            value={formData.leisure_activity}
                            onChange={(e) => handleInputChange('leisure_activity', e.target.value)}
                            required
                        >
                            {activityTypes.map((type) => (
                                <MenuItem key={type} value={type}>{type}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12}>
                    <FormControl fullWidth>
                        <InputLabel>Experience Level</InputLabel>
                        <Select
                            value={formData.experience_level}
                            onChange={(e) => handleInputChange('experience_level', e.target.value)}
                            required
                        >
                            {experienceLevels.map((level) => (
                                <MenuItem key={level} value={level}>{level}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12}>
                    <Button
                        type="submit"
                        variant="contained"
                        color="primary"
                        fullWidth
                        disabled={isGeneratingReport}
                        startIcon={isGeneratingReport ? <CircularProgress size={20} /> : null}
                    >
                        Generate Report
                    </Button>
                </Grid>
            </Grid>
        </Box>
    );
};

export default MainForm;
